import type { NavigationItem } from '~/types/projects/navigation';

interface StatusTabSource {
  value?: string | null;
  name?: string | null;
}

interface BuildMultiSelectStatusTabsOptions<T extends string> {
  source: StatusTabSource[];
  current: T[];
  allCount: number;
  counts: Record<string, number>;
  buildTo: (next: T[]) => NavigationItem['to'];
}

// Builds FilterTabsNav items for a multi-select status filter. Each tab is a real link
// whose `to` toggles a single status in/out of `current` without touching other filters;
// the "all" tab clears the status filter entirely. `buildTo` owns the route-specific link
// construction so the typed-router `to` stays correct per page. Link-based nav means
// clicking a tab always navigates, even when the URL already matches the highlighted state.
export function buildMultiSelectStatusTabs<T extends string>({
  source,
  current,
  allCount,
  counts,
  buildTo,
}: BuildMultiSelectStatusTabsOptions<T>): NavigationItem[] {
  return source.map((item) => {
    const value = item.value ?? 'all';
    const isAll = value === 'all';
    const status = value as T;
    const next = isAll ? [] : current.includes(status) ? current.filter((s) => s !== status) : [...current, status];
    return {
      label: item.name ?? '',
      to: buildTo(next),
      count: isAll ? allCount : (counts[value] ?? 0),
      selected: isAll ? current.length === 0 : current.includes(status),
    };
  });
}
